parts.script:
// Placeholder API call. Replace the URL and the ctx.secrets key name with your real
// ones before this will actually return anything. See js/simulation.js's doc comment
// on ctx.setState for why the response can't just be returned directly from here — a
// fetch's response always arrives after this synchronous script call has returned.
if (!ctx.state.fetching) {
  const url = 'https://api.example.com/data'; // <-- replace with your real endpoint
  fetch(url, {
    headers: { Authorization: 'Bearer ' + ctx.secrets.API_KEY }, // <-- placeholder secret
  })
    .then((r) => r.json())
    .then((data) => ctx.setState({ fetching: false, latest: data }))
    .catch((err) => {
      ctx.log('API call failed: ' + err.message);
      ctx.setState({ fetching: false });
    });
  ctx.log('API call started');
  return { value: ctx.state.latest ?? null, state: { ...ctx.state, fetching: true }, leftBadge: { text: ctx.state.latest ? 'data received' : 'no data yet', color: '#2f8f4e' } };
}
// still waiting on the previous call — hold the last known value
return { value: ctx.state.latest ?? null, state: ctx.state, leftBadge: { text: ctx.state.latest ? 'data received' : 'no data yet', color: '#2f8f4e' } };

// Nothing special needs to happen here for the badge color to change on new data — the
// simulation engine automatically compares this node's value to what it was last tick
// and shows a blue badge whenever it's different. This node just passes through what it
// received, so its badge visibly changes the moment ApiCaller's fetch resolves.
if (ctx.inputs.length === 0) return { value: null, state: {} };
const incoming = ctx.inputs[0].value;
ctx.log('received: ' + JSON.stringify(incoming));
return { value: incoming, state: {}, leftBadge: { text: incoming ? 'data received' : 'no data', color: '#2f8f4e' } };
